const EO_TIERS=["top1k","top10k","top100k"],EO_DEFAULT_TIER="top10k",EO_TEMPLATE=45,EO_DIFFERENTIAL=12;let eoData=null;function eoSetData(data){return eoData=data&&data.players&&data.metadata?data:null,eoData}function eoReady(){return eoData!=null}function eoMeta(){return eoData?eoData.metadata:null}function eoTierLabel(tier){if(tier==="league")return eoLeagueData&&eoLeagueData.label||"Your league";const t=eoData&&eoData.metadata.tiers.find(x=>x.id===tier);return t?t.label:tier}function eoResolution(tier){if(tier==="league")return eoLeagueData&&eoLeagueData.sampled?Math.round(100/eoLeagueData.sampled*100)/100:null;const t=eoData&&eoData.metadata.tiers.find(x=>x.id===(tier||EO_DEFAULT_TIER));return t&&t.sampled?Math.round(100/t.sampled*100)/100:null}function eoFor(playerId,tier){const t=tier||EO_DEFAULT_TIER;if(t==="league"){if(!eoLeagueData)return null;const v2=eoLeagueData.players[String(playerId)];return v2?{eo:v2.eo,own:v2.own,cap:v2.cap,below:!1,tier:t}:{eo:0,own:0,cap:0,below:!0,tier:t}}if(!eoData)return null;const row=eoData.players[String(playerId)],v=row&&row[t];return v?{eo:v.eo,own:v.own,cap:v.cap,below:!1,tier:t}:{eo:0,own:0,cap:0,below:!0,tier:t}}function eoBand(eo){return eo==null?"unknown":eo>=45?"template":eo>=12?"mid":"differential"}function eoText(v){if(!v)return null;if(v.below){const res=eoResolution(v.tier);return res?`under ${res}%`:"0%"}return`${v.eo}%`}function eoSwing(outId,inId,tier){const a=eoFor(outId,tier),b=eoFor(inId,tier);return!a||!b?null:{out:a,in:b,delta:Math.round((b.eo-a.eo)*10)/10,tier:a.tier,label:eoTierLabel(a.tier)}}function eoSquadLoad(squad,tier){if(!eoData||!squad||!squad.length)return null;const t=tier||EO_DEFAULT_TIER,starters=squad.filter(p=>p.pickPosition==null||p.pickPosition<=11);let total=0,counted=0;return starters.forEach(p=>{const v=eoFor(p.id,t);v&&(total+=v.eo*(p.isCaptain?2:1),counted++)}),counted?{total:Math.round(total*10)/10,perStarter:Math.round(total/counted*10)/10,counted,tier:t,label:eoTierLabel(t)}:null}const EO_LEAGUE_MAX=100,EO_LEAGUE_CONCURRENCY=4,EO_LEAGUE_STORE="easyfpl_eo_league";let eoLeagueData=null;function eoLeagueKey(leagueId,gw){return`${EO_LEAGUE_STORE}:${leagueId}:${gw}`}function eoSetLeague(data){return eoLeagueData=data&&data.players?data:null,eoLeagueData}function eoLeagueReady(leagueId,gw){return!!(eoLeagueData&&(leagueId==null||eoLeagueData.leagueId===leagueId)&&(gw==null||eoLeagueData.gw===gw))}function eoLoadCachedLeague(leagueId,gw){try{const raw=JSON.parse(localStorage.getItem(eoLeagueKey(leagueId,gw))||"null");if(raw&&raw.players)return eoSetLeague(raw)}catch{}return null}async function eoSampleLeague(leagueId,gw,label){if(leagueId==null||gw==null)return null;const cached=eoLoadCachedLeague(leagueId,gw);if(cached)return cached;if(typeof fetchWithProxy!="function")return null;const entries=[];for(let page=1;page<=2&&entries.length<EO_LEAGUE_MAX;page++){let data;try{data=await(await fetchWithProxy(`https://fantasy.premierleague.com/api/leagues-classic/${leagueId}/standings/?page_standings=${page}`)).json()}catch{break}const rows=data.standings&&data.standings.results||[];if(!rows.length||(rows.forEach(r=>{entries.length<EO_LEAGUE_MAX&&entries.push(r.entry)}),!data.standings.has_next))break}if(entries.length<4)return null;const squads=[];let cursor=0;if(await Promise.all(Array.from({length:Math.min(EO_LEAGUE_CONCURRENCY,entries.length)},async()=>{for(;cursor<entries.length;){const id=entries[cursor++];try{const picks=(await(await fetchWithProxy(`https://fantasy.premierleague.com/api/entry/${id}/event/${gw}/picks/`)).json()).picks;Array.isArray(picks)&&squads.push(picks)}catch{}}})),squads.length<4)return null;const mult=new Map,owned=new Map,capt=new Map;squads.forEach(picks=>picks.forEach(p=>{mult.set(p.element,(mult.get(p.element)||0)+p.multiplier),owned.set(p.element,(owned.get(p.element)||0)+1),p.is_captain&&capt.set(p.element,(capt.get(p.element)||0)+1)}));const n=squads.length,r1=v=>Math.round(v*10)/10,players={};for(const[id,total]of mult)players[id]={eo:r1(total/n*100),own:r1((owned.get(id)||0)/n*100),cap:r1((capt.get(id)||0)/n*100)};const out={leagueId,gw,label:label||"Your league",sampled:n,players};try{localStorage.setItem(eoLeagueKey(leagueId,gw),JSON.stringify(out))}catch{}return eoSetLeague(out)}
